    name = "text"

    def convert(self, value, param, ctx):
        if isinstance(value, (bytes, bytearray)):
            try:
                return bytes(value).decode("utf-8")
            except UnicodeDecodeError:
                self.fail(f"{value!r} is not valid text.", param, ctx)
        return str(value)


