        lo = "" if self.min is None else f"{self.min}{'<' if self.min_open else '<='}"
        hi = "" if self.max is None else f"{'<' if self.max_open else '<='}{self.max}"
        if lo and hi:
            return f"{lo}x{hi}"
        if lo:
            return f"x{lo[:-1] if lo.endswith('<') else lo}"
        if hi:
            return f"x{hi}"
        return "any value"

    def _range_check(self, value, param, ctx, open_step):
        below = above = False
        if self.min is not None:
            below = value <= self.min if self.min_open else value < self.min
        if self.max is not None:
            above = value >= self.max if self.max_open else value > self.max
        if not (below or above):
