"""Text wrapping and help-page layout helpers."""

import shutil
import textwrap

DEFAULT_WRAP_WIDTH = 100


def terminal_columns():
    return shutil.get_terminal_size((80, 24)).columns


def wrap_text(text, width=None, initial_indent="", subsequent_indent="", preserve_paragraphs=False):
    """Wrap ``text`` to ``width`` columns. Without ``width``, the caller-visible default is used."""
    if width is None:
