    """A confirmation flag (``--yes`` by default) that asks when omitted and aborts when declined."""
    if not param_decls:
        param_decls = ("--yes",)
    kwargs.setdefault("is_flag", True)
    kwargs.setdefault("expose_value", False)
    kwargs.setdefault("prompt", "Do you want to continue?")
    kwargs.setdefault("help", "Confirm the action without prompting.")

    def decorator(f):
        return _attach_param(f, Option(param_decls, **kwargs))

    return decorator


def pass_context(f):
    """Pass the current context as the first positional argument."""

    @functools.wraps(f)
    def new_func(*args, **kwargs):
