    """Pass the current context's author object as the first positional argument."""

    @functools.wraps(f)
    def new_func(*args, **kwargs):
        return f(get_current_context().obj, *args, **kwargs)

    return new_func


def make_pass_decorator(object_type, ensure=False):
    """Return a decorator that passes the nearest author object of ``object_type``."""

    def decorator(f):
        @functools.wraps(f)
        def new_func(*args, **kwargs):
            ctx = get_current_context()
            node = ctx
            found = None
            while node is not None:
                if isinstance(node.obj, object_type):
                    found = node.obj
                    break
                node = node.parent
            if found is None:
                if not ensure:
                    raise RuntimeError(f"Managed to invoke callback without a context object of type {object_type.__name__!r} existing.")
                found = object_type()
                ctx.obj = found
            return f(found, *args, **kwargs)

        return new_func

    return decorator


__all__ = [
    "command", "group", "option", "argument", "help_option", "version_option",
    "custom_version_option", "password_option", "confirmation_option", "pass_context",
    "pass_obj", "make_pass_decorator",
]
_unused = re  # keep module import list stable for readers

