        option("--x", deprecated=True, prompt=True)


# --- FP-09: files and paths --------------------------------------------------------------

def test_file_read_missing_is_usage_error(tmp_path):
    @command()
    @option("--f", type=File("r"))
    def cmd(f):
        pass

    result = invoke(cmd, ["--f", str(tmp_path / "nope.txt")])
    assert result.exit_code == 2
    assert "nope.txt" in result.output


def test_file_write_lazy_then_lazy_failure_is_general_error(tmp_path):
    @command()
    @argument("f", type=File("w"))
    def cmd(f):
        f.write("hello")

    target = tmp_path / "out.txt"
    result = invoke(cmd, [str(target)])
    assert result.exit_code == 0
    assert target.read_text() == "hello"

    bad = tmp_path / "missing-dir" / "x.txt"
    result = invoke(cmd, [str(bad)])
    assert result.exit_code == 1


def test_non_lazy_write_truncates_before_callback(tmp_path):
    target = tmp_path / "t.txt"
    target.write_text("old")

    @command()
    @option("--f", type=File("w", lazy=False))
    def cmd(f):
        pass

    invoke(cmd, ["--f", str(target)])
    assert target.read_text() == ""


def test_atomic_write_keeps_original_until_close(tmp_path):
    target = tmp_path / "a.txt"
    target.write_text("original")

    @command()
    @argument("f", type=File("w", atomic=True))
    def cmd(f):
        f.write("new")
        assert target.read_text() == "original"

    invoke(cmd, [str(target)])
    assert target.read_text() == "new"


def test_dash_stdout_not_closed():
    @command()
    @argument("f", type=File("w"))
    def cmd(f):
        f.write("via dash\n")
        f.close()
        print("after")

    result = invoke(cmd, ["-"])
    assert "via dash" in result.output
    assert "after" in result.output


def test_path_checks(tmp_path):
    existing = tmp_path / "exists.txt"
    existing.write_text("x")

    @command()
    @argument("p", type=Path(exists=True, dir_okay=False))
    def cmd(p):
        print(p)

    assert invoke(cmd, [str(existing)]).exit_code == 0
    assert invoke(cmd, [str(tmp_path)]).exit_code == 2
    assert invoke(cmd, [str(tmp_path / "gone")]).exit_code == 2


def test_path_dash_allowed_without_stream():
    @command()
    @argument("p", type=Path(allow_dash=True))
    def cmd(p):
        print(p)

    assert invoke(cmd, ["-"]).output == "-\n"


def test_filename_format_is_utf8_safe():
    assert optlyn.format_filename(b"caf\xc3\xa9") == "café"
    assert "\\udcff" in optlyn.format_filename(b"\xff")


# --- FP-11: terminal helpers ---------------------------------------------------------------

def test_echo_strips_styles_when_not_terminal():
    @command()
    def cmd():
        echo(style("hi", fg="red"))

    assert invoke(cmd).output == "hi\n"
    assert invoke(cmd, color=True).output == style("hi", fg="red") + "\n"


def test_echo_to_stderr():
    @command()
    def cmd():
        echo("oops", err=True)

    result = invoke(cmd)
    assert result.stdout == ""
    assert result.stderr == "oops\n"


def test_style_roundtrip_and_invalid_color():
    assert unstyle(style("abc", bold=True, fg=(1, 2, 3))) == "abc"
    assert style("x", fg="red") != style("x", bg="red")
    assert style("x", bold=True) != style("x", italic=True)
    with pytest.raises(TypeError):
        style("x", fg="nope")


def test_wrap_text_accepts_any_string():
    assert wrap_text("") == ""
    assert "word" in wrap_text("word " * 50, width=20)


def test_get_app_dir_posix_forced(monkeypatch):
    monkeypatch.setenv("XDG_CONFIG_HOME", "/somewhere")
    assert optlyn.get_app_dir("My App", force_posix=True).endswith("/.my-app")
    if os.name == "posix":
        assert optlyn.get_app_dir("My App").startswith("/somewhere")


def test_clear_does_nothing_when_not_terminal():
    @command()
    def cmd():
        optlyn.clear()

    assert invoke(cmd).output == ""


def test_pause_non_interactive_returns_immediately():
    @command()
    def cmd():
        optlyn.pause("waiting")

    assert invoke(cmd).output == ""


# --- FP-12: shell completion -------------------------------------------------------------

def _complete(cmd, words, cword, prog="tool", shell="bash"):
    env = {
        "_TOOL_COMPLETE": f"{shell}_complete",
        "COMP_WORDS": " ".join(words),
        "COMP_CWORD": str(cword),
    }
    return CliRunner().invoke(cmd, [], env=env, prog_name=prog).output


def test_complete_subcommands_and_options():
    @group()
    def tool():
        pass

    @tool.command()
    def alpha():
        pass

    @tool.command(hidden=True)
    def secret():
        pass

    @tool.command()
    @option("--verbose", is_flag=True)
    def beta(verbose):
        pass

    assert _complete(tool, ["tool", "a"], 1) == "alpha\n"
    assert _complete(tool, ["tool", ""], 1).split() == ["alpha", "beta"]
    assert "--verbose" in _complete(tool, ["tool", "beta", "--"], 2)
    assert _complete(tool, ["tool", "beta", "--"], 2).find("--help") >= 0


def test_complete_choice_values_and_path_request(tmp_path):
    @command()
    @option("--mode", type=Choice(["alpha", "beta"]))
    @argument("f", type=Path())
    def cmd(mode, f):
        pass

    assert _complete(cmd, ["tool", "--mode", "al"], 3, shell="bash") == "alpha\n"
    out = _complete(cmd, ["tool", "x"], 2)
    assert "\x1ffile\x1f" in out


def test_source_script_and_unknown_instruction():
    @command()
    def cmd():
        print("should not run")

    src = CliRunner().invoke(cmd, [], env={"_TOOL_COMPLETE": "bash_source"}, prog_name="tool").output
    assert "complete -o default" in src
    assert "should not run" not in src

    result = CliRunner().invoke(cmd, [], env={"_TOOL_COMPLETE": "nope"}, prog_name="tool")
    assert result.output == ""


def test_completion_ignored_for_other_program_name():
    @command()
    def cmd():
        print("ran")

    result = CliRunner().invoke(cmd, [], env={"_OTHER_COMPLETE": "bash_source"}, prog_name="tool")
    assert result.output == "ran\n"


# --- FP-13: exit statuses ----------------------------------------------------------------

def test_author_exit_status_and_clean_stop():
    @command()
    def stop():
        print("before")
        pass_ctx_exit()
        print("never")

    def pass_ctx_exit():
        get_ctx = optlyn.get_current_context()
        get_ctx.exit(7)

    result = invoke(stop)
    assert result.exit_code == 7
    assert "never" not in result.output


def test_author_abort_exit_one_with_indication():
    @command()
    def cmd():
        raise Abort()

    result = invoke(cmd)
    assert result.exit_code == 1
    assert "Aborted!" in result.output


def test_success_exit_zero():
    @command()
    def cmd():
        pass

    assert invoke(cmd).exit_code == 0


# --- FP-14: in-process runner ------------------------------------------------------------

def test_runner_captures_stdout_stderr_and_exception():
    @command()
    def cmd():
        print("out")
        echo("err", err=True)
        raise ValueError("bad")

    result = invoke(cmd)
    assert result.exit_code == 1
    assert result.stdout == "out\n"
    assert result.stderr == "err\n"
    assert isinstance(result.exception, ValueError)
    assert result.output == "out\nerr\n"


def test_runner_can_propagate_exceptions():
    @command()
    def cmd():
        raise ValueError("bad")

    with pytest.raises(ValueError):
        CliRunner(catch_exceptions=False).invoke(cmd, [])


def test_runner_env_unset_and_restore(monkeypatch):
    monkeypatch.setenv("KEEP_ME", "yes")

    @command()
    def cmd():
        print(os.environ.get("KEEP_ME"), os.environ.get("TEMP_VAR"))

    result = invoke(cmd, env={"KEEP_ME": None, "TEMP_VAR": "t"})
    assert result.output == "None t\n"
    assert os.environ.get("KEEP_ME") == "yes"
    assert "TEMP_VAR" not in os.environ


def test_runner_isolated_filesystem_removed_without_parent(tmp_path):
    runner = CliRunner()
    with runner.isolated_filesystem() as path:
        assert os.getcwd() == os.path.realpath(path)
        leftover = path
    assert not os.path.exists(leftover)

    with runner.isolated_filesystem(temp_dir=str(tmp_path)) as path:
        kept = path
    assert os.path.isdir(kept)


def test_runner_input_is_consumed_and_visible_prompt_echoed():
    @command()
    @option("--name", prompt=True)
    def cmd(name):
        print(name)

    result = invoke(cmd, input="zed\n")
    assert "zed" in result.output


def test_runner_fd_capture_mode():
    @command()
    def cmd():
        os.write(1, b"raw-fd\n")
        print("py")

    result = CliRunner(capture="fd").invoke(cmd, [])
    assert "raw-fd" in result.stdout
    assert "py" in result.stdout


def test_runner_default_capture_has_no_real_fileno():
    @command()
    def cmd():
        try:
            sys_fileno = optlyn.get_current_context().command  # noqa: F841
        except Exception:
            pass
        import sys

        try:
            sys.stdout.fileno()
            print("has-fd")
        except Exception:
            print("no-fd")

    assert invoke(cmd).output == "no-fd\n"


def test_runner_prog_name_and_extra_settings():
    @command()
    @option("--x", type=int, default=1)
    def cmd(x):
        print(optlyn.get_current_context().command_path)

    assert invoke(cmd).output == "cmd\n"


def test_runner_accepts_string_args():
    @command()
    @option("--name")
    def cmd(name):
        print(name)

    assert CliRunner().invoke(cmd, "--name bob").output == "bob\n"


def test_get_current_context_raises_outside_invocation():
    with pytest.raises(RuntimeError):
        optlyn.get_current_context()
    assert optlyn.get_current_context(silent=True) is None


def test_public_exports_present():
    for name in ("command", "group", "option", "argument", "Context", "Command", "Group",
                 "CommandCollection", "BadParameter", "Abort", "STRING", "INT", "FLOAT", "BOOL",
                 "UUID", "UNPROCESSED", "Choice", "DateTime", "IntRange", "FloatRange", "Tuple",
                 "File", "Path", "echo", "secho", "style", "unstyle", "echo_via_pager",
                 "get_pager_file", "progressbar", "prompt", "confirm", "getchar", "pause", "edit",
                 "launch", "clear", "get_app_dir", "get_current_context", "format_filename",
                 "open_file"):
