"""Behavioural tests for Optlyn, organised by feature point of the specification."""

import os
import uuid

import pytest

import optlyn
from optlyn import (
    Abort,
    Choice,
    Context,
    File,
    FloatRange,
    IntRange,
    Path,
    argument,
    command,
    confirmation_option,
    custom_version_option,
    echo,
    group,
    help_option,
    make_pass_decorator,
    option,
    password_option,
    pass_context,
    pass_obj,
    style,
    unstyle,
)
from optlyn.formatting import wrap_text
from optlyn.testing import CliRunner


def invoke(cli, args=None, **kwargs):
    return CliRunner().invoke(cli, args or [], **kwargs)


# --- FP-01: declaration, naming, invocation ----------------------------------------------

def test_name_derivation_strips_suffix_and_dashes():
    @command()
    def init_db_command():
        pass

    @group()
    def tools_grp():
        pass

    assert init_db_command.name == "init-db"
    assert tools_grp.name == "tools"


def test_explicit_name_only_accepts_that_name():
    @command("ship")
    def deploy():
        print("shipped")

    assert invoke(deploy, ["ship"]).output == "shipped\n"
    assert invoke(deploy, ["deploy"]).exit_code == 2


def test_standalone_disabled_returns_value_and_raises_failures():
    @command()
    def add():
        return 42

    assert add.main([], standalone_mode=False) == 42

    @command()
    @option("--n", type=int, required=True)
    def need(n):
        pass

    with pytest.raises(optlyn.BadParameter):
        need.main([], standalone_mode=False)


def test_deprecated_command_runs_and_warns_on_stderr_channel():
    @command(deprecated="use new-thing")
    def old():
        print("ran")

    result = invoke(old)
    assert result.exit_code == 0
    assert "ran" in result.output
    assert "deprecated" in result.output
    assert "use new-thing" in result.output


def test_unknown_option_on_deprecated_command_is_usage_error():
    @command(deprecated=True)
    def old():
        pass

    assert invoke(old, ["--bogus"]).exit_code == 2


def test_extra_arguments_rejected_unless_allowed():
    @command()
    def cmd():
        pass

    assert invoke(cmd, ["extra"]).exit_code == 2

    @command(context_settings={"allow_extra_args": True})
    def cmd2(**kwargs):
        print("ok")

    assert invoke(cmd2, ["extra"]).exit_code == 0


def test_decorator_moves_params_and_redecorating_starts_empty():
    def f(a):
        pass

    option("--a")(f)
    cmd = command()(f)
    assert [p.name for p in cmd.params] == ["a"]
    assert not hasattr(f, "__optlyn_params__")


# --- FP-02: help ----------------------------------------------------------------------------

def test_help_prints_page_and_skips_callback():
    ran = []

    @command()
    @option("--x")
    def cmd(x):
        """Describe things.

        Second paragraph.
        """
        ran.append(x)

    result = invoke(cmd, ["--help"])
    assert result.exit_code == 0
    assert ran == []
    assert "Usage: cmd [OPTIONS]" in result.output
    assert "Describe things." in result.output
    assert "Options:" in result.output
    assert "--x" in result.output


def test_formfeed_truncates_help():
    @command(help="visible\fhidden")
    def cmd():
        pass

    out = invoke(cmd, ["--help"]).output
    assert "visible" in out
    assert "hidden" not in out
    assert "\f" not in out


def test_group_without_subcommand_is_usage_failure_with_help():
    @group()
    def cli():
        """Group help."""

    result = invoke(cli)
    assert result.exit_code == 2
    assert "Group help." in result.output


def test_default_metavar_and_show_default():
    @command()
    @option("--count", type=int, default=3, show_default=True)
    @argument("src")
    def cmd(count, src):
        pass

    out = invoke(cmd, ["--help"]).output
    assert "--count INTEGER" in out
    assert "[default: 3]" in out
    assert "SRC" in out


def test_flag_default_false_is_hidden_when_show_default_on():
    @command(context_settings={"show_default": True})
    @option("--verbose", is_flag=True)
    def cmd(verbose):
        pass

    assert "[default" not in invoke(cmd, ["--help"]).output


def test_version_option_is_eager_and_prints_identity():
    ran = []

    @command()
    @optlyn.version_option("1.2.3", prog_name="tool")
    @option("--must", required=True)
    def cmd(must):
        ran.append(True)

    result = invoke(cmd, ["--version"])
    assert result.exit_code == 0
    assert "1.2.3" in result.output
    assert ran == []


def test_custom_version_option_prints_exact_string():
    @command()
    @custom_version_option(lambda ctx: "custom build 9")
    def cmd():
        pass

    assert invoke(cmd, ["--version"]).output == "custom build 9\n"


def test_first_eager_flag_wins():
    @command()
    @custom_version_option(lambda ctx: "VER")
    @help_option()
    def cmd():
        """Help text."""

    assert invoke(cmd, ["--version", "--help"]).output == "VER\n"
    assert "Help text." in invoke(cmd, ["--help", "--version"]).output


def test_help_option_names_can_be_replaced_via_context():
    @command()
    def cmd():
        """Hi."""

    result = invoke(cmd, ["-h"], help_option_names=["-h"])
    assert result.exit_code == 0
    assert "Hi." in result.output
    assert invoke(cmd, ["--help"], help_option_names=["-h"]).exit_code == 2


def test_author_option_reusing_help_names_wins():
    @command()
    @option("--help", is_flag=True)
    def cmd(help):
        print("author", help)

    assert invoke(cmd, ["--help"]).output == "author True\n"


def test_help_with_no_args_is_help_for_leaf():
    @command(no_args_is_help=True)
    @argument("x", required=False)
    def cmd(x):
        """Leaf help."""

    result = invoke(cmd)
    assert result.exit_code == 2
    assert "Leaf help." in result.output


def test_hidden_option_omitted_from_help_but_accepted():
    @command()
    @option("--secret", hidden=True, default="s")
    def cmd(secret):
        print(secret)

    assert "--secret" not in invoke(cmd, ["--help"]).output
    assert invoke(cmd, ["--secret", "t"]).output == "t\n"


# --- FP-03: options -----------------------------------------------------------------------

def test_stacked_short_flags_and_value_attached():
    @command()
    @option("-a", is_flag=True)
    @option("-b", is_flag=True)
    @option("-n", type=int)
    def cmd(a, b, n):
        print(a, b, n)

    assert invoke(cmd, ["-abn5"]).output == "True True 5\n"
    assert invoke(cmd, ["-ab", "-n", "7"]).output == "True True 7\n"


def test_long_option_equals_and_separate_forms():
    @command()
    @option("--name")
    def cmd(name):
        print(name)

    assert invoke(cmd, ["--name=x"]).output == "x\n"
    assert invoke(cmd, ["--name", "y"]).output == "y\n"


def test_double_dash_ends_options():
    @command()
    @option("--flag", is_flag=True)
    @argument("rest", nargs=-1)
    def cmd(flag, rest):
        print(flag, rest)

    assert invoke(cmd, ["--", "--flag", "x"]).output == "False ('--flag', 'x')\n"


def test_counting_option():
    @command()
    @option("-v", "--verbose", count=True)
    def cmd(verbose):
        print(verbose)

    assert invoke(cmd, ["-vvv"]).output == "3\n"
    assert invoke(cmd).output == "0\n"


def test_repeatable_option_and_multi_value():
    @command()
    @option("--tag", multiple=True)
    @option("--pair", nargs=2, type=int)
    def cmd(tag, pair):
        print(tag, pair)

    result = invoke(cmd, ["--tag", "a", "--tag", "b", "--pair", "1", "2"])
    assert result.output == "('a', 'b') (1, 2)\n"
    assert invoke(cmd, ["--pair", "1"]).exit_code == 2


def test_bare_string_default_on_repeatable_is_usage_error():
    @command()
    @option("--tag", multiple=True, default="x")
    def cmd(tag):
        pass

    result = invoke(cmd)
    assert result.exit_code == 2
    assert "tag" in result.output or "TAG" in result.output


def test_boolean_pair_flags():
    @command()
    @option("--shout/--no-shout", default=False)
    def cmd(shout):
        print(shout)

    assert invoke(cmd, ["--shout"]).output == "True\n"
    assert invoke(cmd, ["--no-shout"]).output == "False\n"


def test_optional_value_option():
    @command()
    @option("--opt", is_flag=False, flag_value="flagged", default="dflt")
    def cmd(opt):
        print(opt)

    assert invoke(cmd).output == "dflt\n"
    assert invoke(cmd, ["--opt"]).output == "flagged\n"
    assert invoke(cmd, ["--opt", "given"]).output == "given\n"


def test_required_option_missing_is_usage_error_and_no_callback():
    ran = []

    @command()
    @option("--req", required=True)
    def cmd(req):
        ran.append(req)

    result = invoke(cmd)
    assert result.exit_code == 2
    assert "--req" in result.output
    assert ran == []


def test_unknown_option_is_usage_error_naming_it():
    @command()
    def cmd():
        pass

    result = invoke(cmd, ["--nope"])
    assert result.exit_code == 2
    assert "--nope" in result.output


def test_ignore_unknown_options_passes_them_to_arguments():
    @command(context_settings={"ignore_unknown_options": True, "allow_extra_args": True})
    @argument("rest", nargs=-1)
    def cmd(rest):
        print(rest)

    assert invoke(cmd, ["--zzz", "a"]).output == "('--zzz', 'a')\n"


def test_alternative_prefix_slash():
    @command()
    @option("/x", is_flag=True)
    def cmd(x):
        print(x)

    assert invoke(cmd, ["/x"]).output == "True\n"


def test_feature_switch_last_declared_wins_on_tie():
    @command()
    @option("--a", "dest", flag_value="A", is_flag=True, default=False)
    @option("--b", "dest", flag_value="B", is_flag=True, default=False)
    def cmd(dest):
        print(dest)

    assert invoke(cmd, ["--a"]).output == "A\n"


def test_callback_refusal_is_usage_error():
    def check(ctx, param, value):
        if value < 0:
            raise optlyn.BadParameter("must be positive", ctx=ctx, param=param)
        return value * 2

    @command()
    @option("--n", type=int, callback=check)
    def cmd(n):
        print(n)

    assert invoke(cmd, ["--n", "4"]).output == "8\n"
    result = invoke(cmd, ["--n", "-1"])
    assert result.exit_code == 2
    assert "must be positive" in result.output


def test_callback_can_default_from_earlier_parameter():
    @command()
    @option("--a", default="x")
    @option("--b", default=None)
    def cmd(a, b):
        print(a, b)

    assert invoke(cmd).output == "x None\n"


# --- FP-04: arguments --------------------------------------------------------------------

def test_arguments_bind_in_order_with_variadic_last():
    @command()
    @argument("first")
    @argument("rest", nargs=-1)
    def cmd(first, rest):
        print(first, rest)

    assert invoke(cmd, ["a", "b", "c"]).output == "a ('b', 'c')\n"
    assert invoke(cmd, ["a"]).output == "a ()\n"


def test_missing_required_argument_names_it():
    @command()
    @argument("target")
    def cmd(target):
        pass

    result = invoke(cmd)
    assert result.exit_code == 2
    assert "TARGET" in result.output


def test_optional_argument_default_and_none_when_absent():
    @command()
    @argument("opt", required=False)
    @argument("dflt", default="d", required=False)
    def cmd(opt, dflt):
        print(opt, dflt)

    assert invoke(cmd).output == "None d\n"


def test_argument_env_requires_explicit_name(monkeypatch):
    monkeypatch.setenv("SRC", "from-env")

    @command()
    @argument("src", required=False)
    def cmd(src):
        print(src)

    assert invoke(cmd).output == "None\n"

    @command()
    @argument("src2", envvar="SRC_NAME", required=True)
    def cmd2(src2):
        print(src2)

    monkeypatch.setenv("SRC_NAME", "named")
    assert invoke(cmd2).output == "named\n"


# --- FP-05: parameter types --------------------------------------------------------------

@pytest.mark.parametrize("token, expected", [("1", True), ("no", False), ("ON", True)])
def test_bool_type(token, expected):
    @command()
    @option("--b", type=optlyn.BOOL)
    def cmd(b):
        print(b)

    assert invoke(cmd, ["--b", token]).output == f"{expected}\n"


def test_int_rejects_fraction():
    @command()
    @option("--n", type=int)
    def cmd(n):
        pass

    assert invoke(cmd, ["--n", "1.5"]).exit_code == 2


def test_choice_returns_original_object_case_insensitive():
    import enum

    class Color(enum.Enum):
        RED = 1

    @command()
    @option("--c", type=Choice(Color, case_sensitive=False))
    def cmd(c):
