import re
pack = None
ranges = {}
for line in open("CHECKLIST.md"):
    m = re.match(r"## Pack (\d+) — (.*)", line)
    if m:
        pack = m.group(1); ranges.setdefault(pack, [m.group(2), []]); continue
    m = re.match(r"- \[ \] (N-\d+)", line)
    if m and pack:
        ranges[pack][1].append(m.group(1))
total = 0
for k in sorted(ranges):
    name, ids = ranges[k]
    total += len(ids)
    if ids:
        print(k, len(ids), ids[0], ids[-1], name)
    else:
        print(k, 0, "-", name)
print("total", total)
